async function getAmountOut(
  tokenAddressIn,
  tokenAddressOut,
  feeUsed,
  amountIn,
  chain
) {
  let amountOut;
  let name = addressToName[tokenAddressIn];
  amountIn = toFixed((amountIn * (await getDecimals(name, chain))).toString());
  let decimals;
  switch (chain) {
    case "0x89": {
      amountOut = await getAmountOutPoly(
        tokenAddressIn,
        tokenAddressOut,
        amountIn,
        feeUsed
      );
      decimals = 10 ** 18;
      break;
    }
    case "0x38": {
      const struct = {
        tokenIn: tokenAddressIn,
        tokenOut: tokenAddressOut,
        amountIn: amountIn,
        fee: feeUsed,
        sqrtPriceLimitX96: 0,
      };
      amountOut = await getAmountOutBNB(struct);
      decimals = 10 ** 18;
      break;
    }
    case "0x2105": {
      const struct = {
        tokenIn: tokenAddressIn,
        tokenOut: tokenAddressOut,
        amountIn: amountIn,
        fee: feeUsed,
        sqrtPriceLimitX96: 0,
      };
      amountOut = await getAmountOutBase(struct);
      decimals = 10 ** 18;
      break;
    }
    case "0xa": {
      const struct = {
        tokenIn: tokenAddressIn,
        tokenOut: tokenAddressOut,
        amountIn: amountIn,
        fee: feeUsed,
        sqrtPriceLimitX96: 0,
      };
      amountOut = await getAmountOutOp(struct);
      decimals = 10 ** 18;
      break;
    }
    case "0xa4ec": {
      const struct = {
        tokenIn: tokenAddressIn,
        tokenOut: tokenAddressOut,
        amountIn: amountIn,
        fee: feeUsed,
        sqrtPriceLimitX96: 0,
      };
      amountOut = await getAmountOutCelo(struct);
      decimals = 10 ** 18;
      break;
    }
    case "0x1": {
      amountOut = await getAmountOutEth(
        tokenAddressIn,
        tokenAddressOut,
        amountIn,
        feeUsed
      );
      decimals = 10 ** 18;
      break;
    }
  }
  return parseInt(amountOut) / decimals;
}

